import{_ as o,l,o as e,c as p,v as t,p as s,x as r,d as P,i as n,S as T}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"PTP","description":"","frontmatter":{"title":"PTP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ptp-precision-time.md","filePath":"cs/ptp-precision-time.md","lastUpdated":1789023840000}'),d={name:"cs/ptp-precision-time.md"};function c(h,a,E,_,m,f){const i=l("Mermaid");return e(),p("div",null,[a[1]||(a[1]=t('<h1 id="ptp" tabindex="-1">PTP <a class="header-anchor" href="#ptp" aria-label="Permalink to &quot;PTP&quot;">​</a></h1><div class="epigraph"><p>PTP 用硬件时间戳与边界/透明时钟补偿交换延迟，把同步推进到微秒–纳秒，服务交易所与 5G RAN，不是 NTP 的换肤。</p><footer>—— 据 IEEE 1588 PTP；ITU-T 电信剖面整理</footer></div><p><a href="/cs/ntp">NTP</a> 到毫秒。<a href="/cs/cellular-ran-core">5G RAN</a> 要更紧。<a href="/cs/ntp">上一课</a> 的软件时间戳被内核与网卡抖动限制。缺口是 <strong>PTP</strong>：硬件戳、BC/TC。本课不把 FTP 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>交易所、基站、数据中心快照要亚微秒。PTP：Sync/Follow_Up/Delay 消息，网卡在 PHY 打戳。边界时钟每跳重新主从；透明时钟把驻留时间写进修正域，避免交换机排队把 NTP 式估计毁掉——直接对应缓冲膨胀与 HOL。要全程支持，一条普通交换机就会毁掉精度。</p><p>不要把 PTP 写成区块链时间。</p><p><span class="marginnote">IEEE 1588。Profile（默认/电信/电力）选定时与消息率。本课不点名交易品种。</span></p><h3 id="要全程硬件戳" tabindex="-1">要全程硬件戳 <a class="header-anchor" href="#要全程硬件戳" aria-label="Permalink to &quot;要全程硬件戳&quot;">​</a></h3><p>透明时钟补偿驻留，普通交换机毁掉精度。服务 RAN 与机房，不服务随意公网主机。与 NTP 不是换肤。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照 NTP 软件戳 vs PTP 硬件戳。画：主时钟 → 支持 PTP 的交换 → 从时钟。与 URLLC：空口同步可源于同一时间底座。</p>',11)),(e(),s(T,null,{default:r(()=>[n(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20GM%5B%22%E5%A4%A7%E4%B8%BB%E9%92%9F%22%5D%20--%3E%20BC%5B%22%E8%BE%B9%E7%95%8C%E6%97%B6%E9%92%9F%22%5D%0A%20%20GM%20--%3E%20TC%5B%22%E9%80%8F%E6%98%8E%E6%97%B6%E9%92%9F%E4%BF%AE%E6%AD%A3%E9%A9%BB%E7%95%99%22%5D%0A%20%20TC%20--%3E%20SL%5B%22%E4%BB%8E%E6%97%B6%E9%92%9F%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[P(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>RoCE 时间戳、Wi‑Fi TSF 是别的钟。安全：未认证 PTP 可被欺骗，要授时网络隔离。ECMP 不对称伤害 delay 测量，PTP 域常固定路径。卫星有传播，但地面 RAN 回传用光纤 PTP。</p><p>与容量无关：同步是控制，不是 \\(C\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 White Rabbit 的全部。FTP 被动模式是下一课。后课默认：微秒级同步要 PTP 与支持的交换；NTP 不够。</p><p>在公网互联网上跑 PTP 没有 hop-by-hop 支持。</p><p>上一课留下的缺口在本课收口；「PTP」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/ftp-passive">FTP 被动模式</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>硬件时间戳 + 交换补偿驻留。</li><li>全程 PTP 感知，否则退回 NTP 精度。</li><li>服务 RAN 与机房，不服务随意主机。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：IEEE 1588。</li></ul>',10))])}const A=o(d,[["render",c]]);export{B as __pageData,A as default};
